import base64

# Let's extract the image data from the prompt
# The base64 in the user prompt is:
# data:image/png;base64,"

b64 = ""

missing_padding = len(b64) % 4
if missing_padding:
    b64 += '=' * (4 - missing_padding)
data = base64.b64decode(b64)
with open("./public/assets/moni-rohan-avatar.png", "wb") as f:
    f.write(data)

print(f"Saved avatar: {len(data)} bytes")
